<?php
namespace App\Http\Controllers\Auth;
use App\Http\Controllers\Controller; use App\Http\Requests\Auth\LoginRequest; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\RateLimiter; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class LoginController extends Controller { public function create(){return view('auth.login');} public function store(LoginRequest $request){$key=Str::transliterate(Str::lower($request->string('email')).'|'.$request->ip()); if(RateLimiter::tooManyAttempts($key,5))throw ValidationException::withMessages(['email'=>'Terlalu banyak percobaan login. Coba lagi nanti.']); if(!Auth::attempt($request->validated(),$request->boolean('remember'))){RateLimiter::hit($key);throw ValidationException::withMessages(['email'=>'Email atau password salah.']);} RateLimiter::clear($key);$request->session()->regenerate();return redirect()->intended(route('dashboard'));} public function destroy(Request $request){Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('login');} }
